mapper.select:
SELECT 
FROM pmis_flow_definition
WHERE flow_code = #{flowCode}
  AND version = #{version}
  AND tenant_id = #{tenantId}
  AND is_publish = 1
  AND status = 'ENABLED'
  AND deleted = 0
LIMIT 1

mapper.update:
UPDATE pmis_flow_definition
SET is_publish = 9,
    updated_by = 0,
    updated_at = CURRENT_TIMESTAMP
WHERE flow_code = #{flowCode}
  AND tenant_id = #{tenantId}
  AND id != #{exceptId}
  AND is_publish = 1
  AND deleted = 0
